"""make_readme_gate41.py <scratchpad> — writes README.md for gate41 (the directory this script lives in). Every figure is READ from the kit's own output
files at the moment it runs (pins_gate41.json, predict_1.out, predict_sim_*.out(.rc), installprobe_gate41.json, fill_1.out, keyscan_1.out, rekey_1.out,
launcher_check_1.out, repin_dryrun_N.out, controls_1.out / controls_2.out (+ .rc), final_lsremote_1.out), each named beside it; the prose (doubts,
questions) is the drafter's. Shape copied from gate40's make_readme (gate39 -> gate38 lineage), re-keyed to gate41. The README ENDS with §8, the ONE
launch command; its argument 2 is the EXISTING scratchpad passed here."""
import json, os, re, glob, hashlib, datetime, sys
D = os.path.dirname(os.path.abspath(__file__)); K = json.load(open(D + '/kit.json')); kit = K['kit']
SP = sys.argv[1] if len(sys.argv) > 1 else ''
if not (SP.startswith('/private/tmp/claude-501/') and '/scratchpad' in SP and os.path.isdir(SP)): sys.exit('usage: make_readme_gate41.py <an EXISTING scratchpad dir under /private/tmp/claude-501/*/scratchpad*> (argument 2 of the launch command)')
P = json.load(open('%s/pins_%s.json' % (D, kit))); IP = json.load(open('%s/installprobe_%s.json' % (D, kit)))
def rd(f): return open(os.path.join(D, f), encoding='utf-8').read() if os.path.exists(os.path.join(D, f)) else ''
def last(f, rx):
    m = [l for l in rd(f).splitlines() if re.search(rx, l)]; return m[-1].strip() if m else 'ABSENT'
def rc(f): return rd(f).strip() or '?'
def strip(s): return re.sub(r'^(PASS )?#1339 ', '', s)
def j(x): return json.dumps(x, ensure_ascii=False, default=str)
